struct Metrics{std::atomic<float> levels[N],adjust[N];std::atomic<unsigned> faults{0};std::atomic<uint64_t> frames{0};Metrics(){for(int i=0;i<N;i++){levels[i]=0;adjust[i]=0;}}};
